    "/api/v1/entitlements/{entitlementId}/change-offering": {
      "patch": {
        "tags": [
          "Entitlement general operations",
          "Zentitle"
        ],
        "summary": "Change entitlement offering",
        "description": "This method allows the change of an entitlement offering. This method can only modify the entitlement
to a different offering if the new offering belongs to the same product.
If the new offering has a lower seat count than the seats currently used in the entitlement,
it will fail unless the 'forceSeatCount' query string parameter is set to true.
If the seat count or overdraft settings were manually edited before, they will not be changed by this method.
This method will also update all entitlement features and attributes to match the new offering,
unless they were previously changed. All usage count feature usages will be reset. If the entitlement
has not been activated yet and the offering has been configured to activate the entitlement upon creation,
it will be applied by this method. For subscription offerings, it will also update the entitlement expiry date
to match the new offering, starting from the current date.",
        "operationId": "Entitlements_ChangeEntitlementOffering",
        "parameters": [
          {
            "name": "entitlementId",
            "in": "path",
            "required": true,
            "description": "Entitlement identifier",
            "schema": {
              "type": "string",
              "format": "EntitlementId",
              "example": "ent_oH_hPJ3BgEO172Yd9-KuTg"
            },
            "x-position": 1
          },
          {
            "name": "forceSeatCount",
            "in": "query",
            "description": "Force seat count change",
            "schema": {
              "type": "boolean"
            },
            "x-position": 2
          }
        ],
        "requestBody": {
          "x-name": "model",
