    "/api/v1/entitlements/{entitlementId}/renew": {
      "patch": {
        "tags": [
          "Entitlement general operations",
          "Zentitle"
        ],
        "summary": "Renew entitlement",
        "description": "Renews a subscription entitlement. This method is specially designed for renewal
of previously activated subscription entitlements. The new expiry date is determined
using following rules:
* If the expiration date has passed but the grace period is active, the new expiry date
will be calculated by adding the subscription period to the current expiry date.
* If the grace period has either expired or not defined at all, the expiry date will
be computed by adding the subscription period to the current date.
* If the expiry date is still in the future, the new expiry date will be determined
by adding the subscription period to the current expiry date.

This method also resets all usage count feature usage at the beginning of the
new subscription period.",
        "operationId": "Entitlements_Renew",
        "parameters": [
          {
            "name": "entitlementId",
            "in": "path",
            "required": true,
            "description": "Entitlement identifier",
            "schema": {
              "type": "string",
