  "components": {
    "schemas": {
      "ActivateEntitlementApiRequest": {
        "type": "object",
        "additionalProperties": false,
        "required": [
          "productId",
          "activationCredentials",
          "seatId"
        ],
        "properties": {
          "productId": {
            "type": "string",
            "description": "Id of a product that will be activated",
            "format": "ProductId",
            "example": "prod_Au_WkJrFzE2HStEdPdRing"
          },
          "activationCredentials": {
            "description": "Credentials required to activate the entitlement",
            "$ref": "#/components/schemas/ActivationCredentialsModel"
          },
          "seatId": {
            "type": "string",
            "description": "Identifier that will identify the computer or account for which activation will be created",
            "maxLength": 100,
            "minLength": 1,
            "example": "user@boeing.com"
          },
          "seatName": {
            "type": "string",
            "description": "Optional name of a seat for the activation",
            "maxLength": 50,
            "nullable": true,
            "example": "User Boeing"
          },
          "editionId": {
            "type": "string",
            "description": "Edition id for activation (optional)",
            "format": "EditionId",
            "nullable": true,
            "example": "ed_yH_hPJ3BgEO187Yd9-kuTg"
          }
        }
      },
      "ActivationAttributeModel": {
        "type": "object",
        "additionalProperties": false,
        "properties": {
          "key": {
            "type": "string",
            "description": "Attribute key",
            "example": "Version"
          },
          "type": {
            "description": "Attribute type",
            "example": "string",
            "$ref": "#/components/schemas/AttributeType"
          },
          "value": {
            "type": "string",
            "description": "Attribute value",
            "nullable": true,
            "example": "1.0.0"
          }
        }
      },
      "ActivationCodeCredentialsModel": {
        "allOf": [
          {
            "$ref": "#/components/schemas/ActivationCredentialsModel"
          },
          {
            "type": "object",
            "additionalProperties": false,
            "required": [
              "code"
            ],
            "properties": {
              "code": {
                "type": "string",
                "description": "Activation code",
                "maxLength": 50,
                "minLength": 1,
                "example": 1234567890
              }
            }
          }
        ]
      },
      "ActivationCodesModel": {
        "type": "object",
        "additionalProperties": false,
        "properties": {
          "activationCodes": {
            "type": "array",
            "description": "Array of activation codes",
            "example": [
              "Y64E-G6QX-56EW-W1BG1"
            ],
            "items": {
              "type": "string"
            }
          }
        }
      },
      "ActivationCredentialsModel": {
        "type": "object",
        "discriminator": {
          "propertyName": "type",
          "mapping": {
            "activationCode": "#/components/schemas/ActivationCodeCredentialsModel",
            "openIdToken": "#/components/schemas/OpenIdTokenCredentialsModel",
            "password": "#/components/schemas/PasswordCredentialsModel"
          }
        },
        "required": [
          "type"
        ],
        "properties": {
          "type": {
            "example": "activationCode",
            "$ref": "#/components/schemas/ActivationMethod"
          }
        }
      },
      "ActivationFeatureModel": {
        "type": "object",
        "additionalProperties": false,
        "properties": {
          "key": {
            "type": "string",
            "description": "Feature key",
            "example": "Workers"
          },
          "type": {
            "description": "Feature type",
            "example": "elementPool",
            "$ref": "#/components/schemas/FeatureType"
          },
          "active": {
            "type": "integer",
            "description": "Amount of feature being currently checked out by activation",
            "format": "int64",
            "nullable": true,
            "example": 1
          },
          "available": {
            "type": "integer",
            "description": "Amount of feature that is still available for checkout (amount form active filed is excluded)",
            "format": "int64",
            "nullable": true,
            "example": 9
          },
          "total": {
            "type": "integer",
            "description": "Total amount of feature in entitlement",
            "format": "int64",
            "nullable": true,
            "example": 10
          },
          "currentUsagePeriodStart": {
            "type": "string",
            "description": "Start of the current usage period. Only applicable for UsageCount features",
            "format": "date-time",
            "nullable": true
          },
          "nextUsagePeriodStart": {
            "type": "string",
            "description": "Start of the next usage period. Only applicable for UsageCount features",
            "format": "date-time",
            "nullable": true
          }
        }
      },
      "ActivationLogModel": {
        "type": "object",
        "additionalProperties": false,
        "properties": {
          "activationId": {
            "type": "string",
            "description": "Activation identifier",
            "format": "ActivationId",
            "nullable": true,
            "example": "act_oH_hPJ3BgE0LTRYd9-k1tg"
          },
          "seatId": {
            "type": "string",
            "description": "Unique id of seat provided by external system",
            "example": "user@boeing.com"
          },
          "timestamp": {
            "type": "string",
            "description": "Operation timestamp",
            "format": "date-time"
          },
          "operation": {
            "description": "Activation operation kind",
            "example": 1,
            "$ref": "#/components/schemas/ActivationOperation"
          },
          "leaseExpiry": {
            "type": "string",
            "description": "Activation lease expiry time",
            "format": "date-time",
            "nullable": true
          },
          "location": {
            "description": "Location from which this activation was requested",
            "$ref": "#/components/schemas/LocationModel"
          }
        }
      },
      "ActivationMethod": {
        "type": "string",
        "description": "",
        "enum": [
          "activationCode",
          "openIdToken",
          "password"
        ]
      },
      "ActivationMode": {
        "type": "string",
        "description": "",
        "enum": [
          "online",
          "offline"
        ]
      },
      "ActivationModel": {
        "type": "object",
        "additionalProperties": false,
        "properties": {
          "id": {
            "type": "string",
            "description": "Activation identifier",
            "format": "ActivationId",
